F.log(1,kOe[2705],string.format(kOe[2756],V.name(Er.id),Er.g.name,pb.words(pb.withBook(Er.id,Er.g)),pb.SURE_WORDS[Er.e.sure]or tostring(Er.e.sure),tostring(Er.e.why)))
elseif Cr and Er.id==bb.trialId then
