function pb.model(Zr,as,bs)
local cs=tostring(Zr)..kOe[2458]..tostring(bs and bs.atk)..kOe[2458]..tostring(bs and bs.cd)
local ds=pb._model[cs]
if ds~=nil then
return ds or nil
end
local es,fs={},false
local gs=math.max(0.3,tonumber(bs and bs.cd)or 2)
local hs=math.min(1,(tonumber(as and as.n)or 1)/4)
local js,ks=pcall(pb.guess,Zr)
local ls,ms={},{}
for ns,ps in ipairs(js and type(ks)==kOe[2316]and ks or{})do
if ps.hand then
ls[ps.pid]=true
end
ms[ps.pid]=ps.nums
end
for qs,rs in pairs(pb.rules(Zr))do
if not ls[qs]then
local ss={}
for ts,us in pairs(type(ms[qs])==kOe[2316]and ms[qs]or{})do
ss[ts]=us
end
for vs,ws in pairs(type(rs.nums)==kOe[2316]and rs.nums or{})do
ss[vs]=ws
end
local xs=rs.trigger~=nil and tostring(rs.trigger):find(kOe[2734],1,true)~=nil
if rs.family==kOe[2516]then
local ys=(xs and pb.ABILITY_UPTIME or 1)*(rs.who==kOe[2584]and pb.RANGE_SHARE or 1)
local zs=es.aura or{typed={}}
for As,Bs in pairs(type(ss.typed)==kOe[2316]and ss.typed or{})do
