function hb.relicRefresh()
local Cbb=P.relic
Cbb.items,Cbb.need={},{}
if not O.relicFarm then
Cbb.target=nil
return nil
end
local Dbb=tostring(O.relicTarget or kOe[1235])
local Ebb,Fbb,Gbb
for Hbb,Ibb in ipairs(hb.relicList())do
if Dbb==kOe[1235]or Dbb==Ibb.id then
local Jbb,Kbb,Lbb=hb.relicNeed(Ibb.id)
local Mbb,Nbb,Obb,Pbb=hb.relicRuns(Jbb)
local Qbb=hb.relicGain(Ibb.id)
local Rbb= #Obb==0 and Qbb/(Mbb+5)or-1
local Sbb={id=Ibb.id,name=Ibb.name,miss=Jbb,crafts=Kbb,gold=Lbb,runs=Mbb,byLevel=Nbb,nosrc=Obb,at=Pbb,gain=Qbb,score=Rbb}
local Tbb=kb.relicBar()
if Dbb==kOe[1235]and Ibb.id==Cbb.target and Qbb>Tbb and#Obb==0 then
Gbb=Sbb
end
if Dbb==Ibb.id or(Qbb>Tbb and#Obb==0 and(not Fbb or Rbb>Fbb))then
Ebb,Fbb=Sbb,Rbb
end
end
end
if Gbb and Ebb and Ebb~=Gbb and(tonumber(Ebb.score)or 0)<(tonumber(Gbb.score)or 0)*1.5 then
Ebb=Gbb
end
Cbb.target=Ebb and Ebb.id or nil
if not Ebb then
Cbb.name,Cbb.runs,Cbb.gain,Cbb.where,Cbb.gold,Cbb.nosrc,Cbb.ready=nil,nil,nil,nil,nil,nil,nil
return nil
end
local Ubb,Vbb,Wbb=math.max(0.0001,Ebb.runs),nil,-1
for Xbb,Ybb in pairs(Ebb.byLevel)do
local Zbb=0
for _bb,acb in pairs(Ebb.at)do
if acb.level==Xbb then
Zbb=Zbb+Ebb.miss[_bb]/acb.per
end
end
for bcb,ccb in pairs(Ebb.at)do
if ccb.level==Xbb and Zbb>0 then
local dcb=(Ebb.miss[bcb]/ccb.per)/Zbb
Cbb.items[bcb]=(tonumber(O.relicValue)or 3000)*(Ybb/Ubb)/Ybb*dcb/ccb.per
Cbb.need[bcb]=Ebb.miss[bcb]
end
end
if Ybb>Wbb then
Vbb,Wbb=Xbb,Ybb
end
end
Cbb.name,Cbb.runs,Cbb.gain,Cbb.where,Cbb.gold,Cbb.nosrc=Ebb.name,Ebb.runs,Ebb.gain,Vbb,Ebb.gold,#Ebb.nosrc>0 and Ebb.nosrc or nil
Cbb.ready=next(Ebb.miss)==nil
Cbb.crafts=Ebb.crafts
return Ebb
end
