rcb.sell=pcb.rack_count(mcb)+(tonumber(vcb)or 0)
rcb.coins=pcb.rack_value(mcb)
local wcb=math.max(0,ocb-scb)
if qcb.upgrade then
local xcb
for ycb,zcb in ipairs({kOe[3379],kOe[3380]})do
local Acb=tonumber(zcb==kOe[3379]and mcb.f or mcb.s)or 1
local Bcb=Acb<pcb.max_level(zcb)and pcb.get_level(zcb,Acb+1)or nil
local Ccb=Bcb and tonumber(Bcb.cost)or nil
if Ccb and Ccb<=wcb and(not xcb or Ccb<xcb.cost)then
xcb={kind=zcb,cost=Ccb,to=Acb+1}
end
end
if xcb then
rcb.upgrade=xcb
wcb=wcb-xcb.cost
end
end
