function kb.gainXp(qgb,rgb)
local sgb,tgb=tonumber(qgb.xp)or 0,kb.xpFor(qgb.unit_id,kb.cap(qgb))
local ugb=math.max(0,tgb-sgb)
if ugb<=0 or(rgb or 0)<=0 then
return 0,0
end
local vgb=math.min(rgb,ugb)
local wgb=kb.base(qgb)
if wgb<=0 then
return 0,vgb
end
return kb.share(qgb.unit_id)*(kb.score(kb.whatIf(qgb,{xp=sgb+vgb}))/wgb-1)*100,vgb
end
