function kb.relicWorth(xgb,ygb)
local zgb=ygb._unique_item_data and ygb._unique_item_data._unique_relic_data
if not zgb then
return 0
end
local Agb=N.Items[ygb.item_id]or{}
local Bgb,Cgb=V.types(xgb.unit_id)
if Agb.main_damage_type and Agb.main_damage_type~=kOe[3027]and Agb.main_damage_type~=Cgb then
return 0
end
local Dgb,Egb=0,0
for Fgb,Ggb in pairs(zgb._core_damage_type_buffs or{})do
if Bgb[Ggb.damage_type]then
Dgb=Dgb+(tonumber(Ggb.mul)or 0)+(tonumber(Ggb.add_upg)or 0)*0.01+(tonumber(Ggb.pen)or 0)*0.001
Egb=Egb+(tonumber(Ggb.crit)or 0)
end
end
Dgb=Dgb+Egb*0.5
local Hgb=V.rows(xgb.unit_id)
local Igb=Hgb and Hgb[Hgb.max]
local Jgb=(Igb and tonumber(Igb.cd)or 0)*V.mult(xgb,kOe[2767])
for Kgb,Lgb in pairs(zgb._unique_relic_effects or{})do
local Mgb=type(Lgb.params)==kOe[2316]and Lgb.params or{}
if Lgb.id==kOe[3432]then
local Ngb=math.min(1,(tonumber(Mgb.extra_damage)or 0)*Jgb/math.max(1,tonumber(Mgb.time_interval)or 40))
local Ogb=V.DRONES and V.DRONES[xgb.unit_id]
if Ogb and Ogb.late and Jgb>0 then
local Pgb=1/Jgb
Ngb=Ngb*Pgb/(Pgb+(tonumber(Ogb.max)or 0)*(tonumber(Ogb.late.dmg)or 0)*(tonumber(Ogb.hits)or 1)/math.max(0.1,tonumber(Ogb.late.cd)or 4))
end
Dgb=Dgb+Ngb
elseif Lgb.id==kOe[3433]then
Dgb=Dgb+(tonumber(Mgb.dmg_buff)or 0)*0.25
elseif Lgb.id==kOe[3434]then
Dgb=Dgb+(tonumber(Mgb.dmg_buff)or 0)*Egb
elseif Lgb.id==kOe[3435]then
if Bgb.magic then
Dgb=0
else
Dgb=Dgb+(tonumber(Mgb.dmg_buff)or 0)*0.3
end
elseif Lgb.id==kOe[3436]then
if Bgb.water_damage then
Dgb=Dgb+0.05
end
elseif Lgb.id==kOe[2468]then
local Qgb=tonumber(Mgb.duration_buff)or tonumber(type(Lgb.static_params)==kOe[2316]and Lgb.static_params.duration_buff)or 2
local Rgb,Sgb=pcall(V.attackInfo,Igb and Igb.atk,Igb and Igb.range)
local Tgb,Ugb=Rgb and tonumber(Sgb.burn)or 0,Rgb and tonumber(Sgb.dot)or 0
if Tgb<=0 then
local Vgb,Wgb=pcall(pb.model,xgb.unit_id,Rgb and Sgb or nil,Igb)
if Vgb and type(Wgb)==kOe[2316]and(tonumber(Wgb.burnDot)or 0)>0 then
Tgb,Ugb=Wgb.burnDot,Ugb+(tonumber(Wgb.dot)or 0)
end
end
Dgb=Dgb+Tgb*math.max(0,Qgb-1)/(1+Ugb)
end
end
return Dgb
end
