local lHb=kHb.unit_id
if not dHb[jHb]and not dHb[lHb]and N.Units[lHb]and not V.isFarm(lHb)and not V.allyBuff(lHb)and os.time()-(tonumber(aHb.tried[lHb])or 0)>ab.LAB.AGAIN then
