end
local pHb,qHb
for rHb,sHb in ipairs(cHb)do
if not V.isFarm(sHb.id)and not V.allyBuff(sHb.id)and sHb.uuid~=O.evolveUnit then
local tHb=kb.score(sHb.u)
if not pHb or tHb<qHb then
pHb,qHb=sHb,tHb
end
end
end
