function eb.upgradeGain(PMb,QMb,RMb,SMb,TMb,UMb)
local VMb,WMb=QMb[RMb],QMb[RMb+1]
local XMb=(VMb.cd>0 and VMb.damage/VMb.cd or 0)
local YMb=(WMb.cd>0 and WMb.damage/WMb.cd or 0)*V.aoe(WMb.atk,WMb.range)/math.max(0.3,V.aoe(VMb.atk,VMb.range))
local ZMb=XMb>0 and PMb*(YMb/XMb-1)or(UMb or 0)
local _Mb=QMb[RMb+2]
if _Mb and RMb+1<QMb.max and _Mb.cd>0 and WMb.cd>0 and XMb>0 then
local aNb=PMb*((_Mb.damage/_Mb.cd)/XMb-1)
local bNb=SMb+_Mb.cost*TMb
if aNb/bNb>ZMb/SMb then
ZMb=ZMb+(aNb/bNb*SMb-ZMb)*0.5
end
end
local cNb=(WMb.range or 0)>(VMb.range or 0)and(1+((WMb.range-VMb.range)/math.max(1,VMb.range)))or 1
return math.max(0,ZMb)*cNb
end
function eb.dpsFor(dNb,eNb)
if eNb<=0 then
return 0
end
local fNb={}
for gNb,hNb in ipairs(dNb)do
if not hNb.farm and not hNb.grif and hNb.gain>0 then
table.insert(fNb,hNb)
end
end
table.sort(fNb,function(iNb,jNb)
return iNb.gain/iNb.cost>jNb.gain/jNb.cost
end)
local kNb,lNb=0,0
for mNb,nNb in ipairs(fNb)do
if eNb<=0 then
break
end
lNb=nNb.gain/nNb.cost
local oNb=math.min(1,eNb/nNb.cost)
kNb=kNb+nNb.gain*oNb
eNb=eNb-nNb.cost*oNb
end
return kNb+math.max(0,eNb)*lNb*0.7
end
function eb.shieldDps(pNb,qNb,rNb,sNb,tNb,uNb,vNb)
if(sNb or 0)<=0 or(pNb or 0)<=0 or(tNb or 0)<=0 then
return pNb or 0
end
qNb,rNb,uNb=math.max(0.3,qNb or 2),math.max(1,rNb or 1),uNb or 1
local wNb=pNb*uNb*qNb/rNb
return tNb*rNb/((sNb/math.max(1,vNb or 1)+math.max(1,tNb/wNb))*qNb)/uNb
end
function eb.shieldGain(xNb,yNb,zNb,ANb,BNb,CNb,DNb,ENb)
local FNb,GNb=V.attackInfo(yNb.atk,yNb.range),V.attackInfo(ANb.atk,ANb.range)
local HNb=eb.shieldDps(xNb,(tonumber(yNb.cd)or 2)*(DNb or 1),FNb.n,BNb,CNb,ENb,FNb.hits)
local INb=eb.shieldDps(zNb,(tonumber(ANb.cd)or 2)*(DNb or 1),GNb.n,BNb,CNb,ENb,GNb.hits)
local JNb=math.max(0,((tonumber(ANb.range)or 0)-(tonumber(yNb.range)or 0))/math.max(1,tonumber(yNb.range)or 1))
return math.max(0,INb-HNb)+HNb*JNb
end
function eb.shieldWork(KNb,LNb,MNb,NNb,ONb,PNb,QNb,RNb,SNb)
if(NNb or 0)<=0 then
return 0
end
local TNb=3*NNb*(ONb or 1)/math.max(1,PNb or 20)
if(MNb or 0)>=TNb then
return 0
end
return math.max(1,KNb or 1)*math.max(1,SNb or 1)/math.max(0.3,LNb or 2)*math.min(QNb or 0,RNb or 0)
end
function eb.holdGain(UNb,VNb,WNb,XNb)
if not UNb or(VNb or 0)<=0 then
return 0
end
local YNb,ZNb=tonumber(UNb.stun)or 0,tonumber(UNb.slowTime)or 0
if YNb<=0 and ZNb<=0 then
return 0
end
local _Nb,aOb=YNb>0 and YNb or ZNb,YNb>0 and 1 or(tonumber(UNb.slowPct)or 0.3)
local bOb=aOb*_Nb/(_Nb+(tonumber(UNb.ccCd)or 8))
local cOb=bOb/math.max(0.1,1-bOb)
return VNb*cOb*U.clamp(WNb or 0.5,0,1)*math.min(1,(tonumber(UNb.n)or 1)/2)/(1+(XNb or 0))
end
function eb.bleedGain(dOb,eOb,fOb,gOb)
if(dOb or 0)<=0 then
return 0
end
local hOb=eOb or 0
for iOb,jOb in ipairs(fOb or{})do
hOb=math.max(hOb,(tonumber(jOb.hp)or 0)*0.5)
end
return dOb*hOb*(gOb and 0.5 or 1)
end
function eb.bleedShare(kOb,lOb,mOb,nOb)
if kOb<=0 or not lOb then
return 0
end
if nOb then
return lOb==0 and kOb or kOb/(lOb+1)
end
return mOb<lOb and kOb/(lOb-mOb)or 0
end
function eb.keepsUp(oOb,pOb,qOb,rOb,sOb)
local tOb=oOb.coming
if not(tOb and#tOb>0 and oOb.waveSec)then
return true
end
local uOb=oOb.eff or 1
local vOb=oOb.money-qOb
local wOb=(oOb.teamDps or 0)*(oOb.shieldK or 1)+(rOb or 0)*uOb+eb.dpsFor(pOb,math.max(0,vOb))*uOb
local xOb=(oOb.farmNow or 0)+(sOb or 0)
local yOb=(oOb.roadSec or 130)*U.clamp(oOb.cover or 0.6,0.1,1)
local zOb=oOb.hpAlive or 0
for AOb,BOb in ipairs(tOb)do
zOb=math.max(0,zOb+BOb.hp-wOb*oOb.waveSec)
local COb=wOb*yOb
if zOb>COb then
return false,AOb,COb/math.max(1,zOb)
end
if AOb< #tOb then
wOb=wOb+eb.dpsFor(pOb,(BOb.reward or 0)+xOb)*uOb*(0.85^AOb)
end
end
return true
end
eb.BOX_FROM=0.15
function eb.boxFrom(DOb)
local EOb=0
for FOb,GOb in ipairs(DOb)do
EOb=EOb+GOb.w
end
if EOb<=0 then
return nil
end
table.sort(DOb,function(HOb,IOb)
return HOb.p<IOb.p
end)
local JOb=0
for KOb,LOb in ipairs(DOb)do
JOb=JOb+LOb.w
if JOb>=EOb*eb.BOX_FROM then
return LOb.p
end
end
return nil
end
function eb.boxPressure(MOb,NOb,OOb)
if not NOb or NOb<=0.05 or OOb<=NOb+0.05 then
return MOb
end
return OOb*U.clamp((MOb-NOb)/(OOb-NOb),0,1)
end
function eb.decide(POb,QOb)
local ROb=U.clamp(QOb.cover or 0.6,0.1,1)
local SOb=eb.boxPressure(QOb.pressure,QOb.boxFrom,ROb)
local TOb=math.max(O.clearSec,0.7*(QOb.roadSec or 50)*ROb)
local UOb=(QOb.clearSec or 0)>TOb
QOb.piling=QOb.piling and UOb
local VOb=QOb.attackers>0 and SOb<math.min(O.safeReach,ROb*0.75)and not QOb.piling and not UOb
local WOb=SOb>=math.min(O.dangerReach,ROb*0.9)or(QOb.piling and QOb.enemies>=18)
local XOb,YOb
for ZOb,_Ob in ipairs(POb)do
if _Ob.farm then
if O.farmUnits and _Ob.gain>0 then
_Ob.payback=_Ob.cost/_Ob.gain
if QOb.left-1>=_Ob.payback+(QOb.farmSpare or O.farmSpare)and(not XOb or _Ob.payback<XOb.payback)then
XOb=_Ob
end
end
else
_Ob.ratio=_Ob.gain/math.max(1,_Ob.cost)
if not YOb or _Ob.ratio>YOb.ratio then
YOb=_Ob
end
end
end
if QOb.leak and QOb.attackers>0 then
local aPb
for bPb,cPb in ipairs(POb)do
local dPb=not QOb.airLeak or(cPb.e and bb.cardAir(cPb.e.id))
if cPb.place and not cPb.farm and not cPb.idol and not cPb.grif and dPb and cPb.cost<=QOb.money and not(cPb.e and V.allyBuff(cPb.e.id))and(not aPb or cPb.gain>aPb.gain)then
aPb=cPb
end
end
if aPb then
return aPb,string.format(kOe[4137],math.floor(QOb.leak*100))
end
end
local ePb=QOb.future<QOb.wantLeft*1.1
local fPb,gPb,hPb=true,nil,nil
if XOb then
fPb,gPb,hPb=eb.keepsUp(QOb,POb,XOb.cost,0,XOb.gain)
end
local iPb=QOb.coming and not eb.keepsUp(QOb,POb,0,0,0)
local jPb=false
if bb.random and XOb and not WOb and QOb.attackers>=2 and XOb.payback<=QOb.left/3 then
local kPb=0
for lPb,mPb in ipairs(bb.mine or{})do
if V.isFarm(mPb._stats.id.Value)then
kPb=kPb+1
end
end
jPb=not XOb.place or kPb<4
end
if iPb and QOb.attackers>0 then
WOb=true
end
if WOb and YOb and YOb.grif then
YOb=nil
for nPb,oPb in ipairs(POb)do
if not oPb.farm and not oPb.grif and(not YOb or oPb.ratio>YOb.ratio)then
YOb=oPb
end
end
end
local pPb=math.max(1,QOb.incomeRate or 20)
local qPb=QOb.waveSec or 20
local function rPb(sPb,tPb,uPb)
local vPb=math.max(0,(sPb.cost-QOb.money)/pPb)
local wPb=sPb.gain*math.max(0,uPb-vPb)
if tPb then
local xPb=math.max(0,QOb.money-sPb.cost)
local yPb=vPb+math.max(0,(tPb.cost-xPb)/pPb)
wPb=wPb+tPb.gain*math.max(0,uPb-yPb)
end
return wPb
end
