function gb.evaluate(pic,qic)
local ric=gb.run(pic,qic,{hpMul=1})
local sic={won=ric.won,wave=ric.wave,minutes=ric.t/60,aliveAt=ric.aliveAt,total=pic.total,at=os.time()}
