elseif ric.won then
local tic=gb.run(pic,qic,{hpMul=1.3})
sic.p=tic.won and 0.92 or 0.7
sic.margin=tic.won and kOe[4256]or kOe[4257]
else
local uic=gb.run(pic,qic,{hpMul=0.75})
sic.p=uic.won and 0.25 or 0.05
sic.margin=uic.won and string.format(kOe[4258],ric.wave)or string.format(kOe[4259],ric.wave,pic.total)
if not uic.won then
local vic=gb.run(pic,qic,{hpMul=0.25})
if not vic.won then
sic.p,sic.hopeless=0.005,true
