if(Fed.stun or 0)<=0 and(Fed.slowTime or 0)<=0 then
return 0
end
local Ged=0
for Hed,Ied in ipairs(bb.mine or{})do
local Jed=Ied._stats
local Ked=V.rows(Jed.id.Value)
local Led=Ked and Ked[math.min(Jed.upgrade.Value,Ked.max)]
local Med=Led and Led.atk and V.attackInfo(Led.atk,Led.range)
if Med and((Med.stun or 0)>0 or(Med.slowTime or 0)>0)then
Ged=Ged+1
end
end
local Ned,Oed=gb.mask(bb.info.map,V.range(Ded.u,0)*(bb.info.rangeScale or 1)),0
for Ped=1,gb.BINS do
if Ned[Ped]then
Oed=Oed+1
end
end
local Qed=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local Red=(V.airFrom(Ded.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
