function bb.buffGain(Sed)
local Ted=V.allyBuff(Sed.id)
if not Ted or O.actives==false then
return 0
end
local Ued,Ved,Wed=bb.buffShort(Ted)
local Xed=V.stackCap(Ted.attack)
local Yed,Zed=pcall(V.range,Sed.u,0)
Zed=(Yed and tonumber(Zed)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local _ed=Xed and O.community and tonumber(Ted.time)and tonumber(Wed)
local function afd(bfd,cfd)
local dfd=math.floor(bfd*Ted.time/math.max(1,Wed)+0.001)
return math.min(Xed,(1+cfd)^dfd-1)
end
local efd=0
for ffd,gfd in ipairs(Ued)do
local hfd=0
for ifd,jfd in ipairs(Ued)do
if(jfd.pos-gfd.pos).Magnitude<=Zed then
local kfd=Ted.types[jfd.base]
local lfd=kfd*Ted.uptime
if _ed then
local mfd,nfd=afd(jfd.n,kfd),jfd.n+1
while nfd<jfd.n+6 and afd(nfd,kfd)<=mfd+0.001 do
nfd=nfd+1
end
lfd=math.max(0,(afd(nfd,kfd)-mfd)/(nfd-jfd.n))
elseif Xed then
lfd=math.max(0,math.min(Xed,(jfd.n+1)*kfd*Ted.uptime)-math.min(Xed,jfd.n*kfd*Ted.uptime))
end
hfd=hfd+jfd.dps*lfd
end
end
efd=math.max(efd,hfd)
end
return efd*(_ed and 1 or 0.7)
end
function bb.buffWanted(ofd)
