for kmd=0,11 do
local lmd=kmd*math.pi/6+jmd
table.insert(fmd,Vector3 .new(dmd.p.X+math.cos(lmd)*dmd.r*jmd,dmd.y,dmd.p.Z+math.sin(lmd)*dmd.r*jmd))
end
