end
local qmd=bb.valid(pmd,cmd)
local rmd=qmd and(U.flat(qmd)-dmd.p).Magnitude
if rmd and rmd<=emd and(not nmd or rmd<nmd)then
mmd,nmd=qmd,rmd
end
end
