if not bb.infinite and bb.total and bb.wave()>=bb.total-2 then
return false
end
local Xnd,Ynd=U.flat(Tnd:GetPivot().Position),tonumber(Und.range.Value)or 0
local Znd,_nd,aod,bod=0,{},0,{}
for cod,dod in ipairs(bb.mine or{})do
local eod=dod~=Tnd and dod:FindFirstChild(kOe[2388])
local fod=eod and eod:FindFirstChild(kOe[2709])and eod.id.Value
if fod and(U.flat(dod:GetPivot().Position)-Xnd).Magnitude<=Ynd then
if V.sacFodder(fod)then
Znd=Znd+1
local god=eod:FindFirstChild(kOe[4618])and tonumber(eod.total_spent.Value)or 0
aod=aod+god
bod[dod]=god
else
_nd[V.name(fod)]=true
