function bb.huntWeakText()
local dsd=type(P.hunt)==kOe[2316]and P.hunt.runs or{}
if#dsd<bb.HUNT_WEAK_RUNS then
return nil
end
local esd,fsd,gsd=0,0,{}
for hsd=1,bb.HUNT_WEAK_RUNS do
local isd=dsd[hsd]
if type(isd)~=kOe[2316]or isd.won then
return nil
end
esd,fsd=esd+(tonumber(isd.pearls)or 0),fsd+(tonumber(isd.sec)or 0)
table.insert(gsd,tonumber(isd.wave)or 0)
end
if fsd<=0 then
return nil
end
table.sort(gsd)
local jsd=gsd[math.ceil(#gsd/2)]
local ksd=esd/fsd*60*(tonumber(O.pearlValue)or 0.35)
local lsd={string.format(kOe[5015],bb.HUNT_WEAK_RUNS,jsd,ksd)}
local msd
for nsd,osd in ipairs(W.lastScored or{})do
if osd.kind~=kOe[2339]and(tonumber(osd.score)or 0)>0 then
msd=osd
break
end
end
if msd then
table.insert(lsd,string.format(kOe[5016],tostring(msd.label),msd.score))
end
local psd=0
for qsd,rsd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[rsd]==false then
psd=psd+1
end
end
if W.onlyOn()then
table.insert(lsd,kOe[5017])
elseif psd>=4 then
table.insert(lsd,string.format(kOe[5018],psd))
end
table.insert(lsd,kOe[5019])
return table.concat(lsd,kOe[2707]),ksd,jsd
end
