function bb.learn()
local ptd=bb.calRun and bb.calRun.potBy
if type(ptd)~=kOe[2316]then
return
end
pcall(bb.sampleHelpers,true)
local qtd={}
for rtd,std in pairs(bb.ownDealt or{})do
if not V.isFarm(std.id)then
qtd[std.id]=(qtd[std.id]or 0)+(tonumber(std.v)or 0)
end
end
for ttd,utd in pairs(bb.helperDealt or{})do
if utd.owner and V.SUMMONER[utd.owner]and not V.droneHelper(utd)then
qtd[utd.owner]=(qtd[utd.owner]or 0)+(tonumber(utd.v)or 0)
end
end
local vtd=type(bb.calRun.potExp)==kOe[2316]and bb.calRun.potExp or{}
local wtd,xtd=0,0
local ytd={}
for ztd,Atd in pairs(ptd)do
if Atd>0 then
wtd,xtd=wtd+(qtd[ztd]or 0),xtd+Atd
local Btd=tonumber(vtd[ztd])or Atd
if Btd>0 then
table.insert(ytd,{id=ztd,r=(qtd[ztd]or 0)/Btd,w=Btd})
end
end
end
if wtd<=0 or xtd<=0 then
return
end
table.sort(ytd,function(Ctd,Dtd)
return Ctd.r<Dtd.r
end)
local function Etd(Ftd)
local Gtd,Htd=0,0
for Itd,Jtd in ipairs(ytd)do
if Jtd.id~=Ftd then
Gtd=Gtd+Jtd.w
end
end
if Gtd<=0 then
return nil
end
for Ktd,Ltd in ipairs(ytd)do
if Ltd.id~=Ftd then
Htd=Htd+Ltd.w
if Htd>=Gtd/2 then
return Ltd.r
end
end
end
end
bb.lastEff={}
for Mtd,Ntd in pairs(ptd)do
local Otd=Etd(Mtd)
if Ntd>0 and Ntd/xtd>0.02 and Otd and Otd>0 then
local Ptd=P.learn[Mtd]or{eff=1,n=0,v=6}
V.learnUp(Mtd,Ptd)
local Qtd=math.max(0.02,0.25*math.sqrt(30/(30+Ptd.n)))
local Rtd=U.clamp(((qtd[Mtd]or 0)/Ntd)/Otd,0.2,6)
bb.lastEff[Mtd]=math.floor(Rtd*1000+0.5)/1000
Ptd.eff=Ptd.eff+(Rtd-Ptd.eff)*Qtd
Ptd.n=Ptd.n+1
P.learn[Mtd]=Ptd
end
end
local Std=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Std and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==kOe[2316]and P.mapLearn or{}
local Ttd=type(P.mapLearn[Std])==kOe[2316]and P.mapLearn[Std]or{}
for Utd,Vtd in pairs(bb.lastEff)do
local Wtd=type(Ttd[Utd])==kOe[2316]and Ttd[Utd]or{eff=Vtd,n=0,v=6}
if(tonumber(Wtd.v)or 0)<4 then
Wtd.eff,Wtd.v=(tonumber(Wtd.eff)or Vtd)*V.secRescale(Utd),4
end
if(tonumber(Wtd.v)or 0)<5 then
Wtd.eff,Wtd.v=(tonumber(Wtd.eff)or Vtd)*(V.sumRescale(Utd)or 1),5
end
if(tonumber(Wtd.v)or 0)<6 then
Wtd.eff,Wtd.v=(tonumber(Wtd.eff)or Vtd)*(1-(V.SUMMONER[Utd]and V.SUMMONER[Utd].droneShare or 0)),6
end
local Xtd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Wtd.n)or 0))))
Wtd.eff=(tonumber(Wtd.n)or 0)==0 and Vtd or((tonumber(Wtd.eff)or Vtd)+(Vtd-(tonumber(Wtd.eff)or Vtd))*Xtd)
Wtd.n=(tonumber(Wtd.n)or 0)+1
Ttd[Utd]=Wtd
end
Ttd._at=os.time()
P.mapLearn[Std]=Ttd
if U.count(P.mapLearn)>80 then
local Ytd,Ztd
for _td,aud in pairs(P.mapLearn)do
if not Ztd or(tonumber(aud._at)or 0)<Ztd then
Ytd,Ztd=_td,tonumber(aud._at)or 0
end
end
P.mapLearn[Ytd]=nil
end
end
end
function bb.randomTeam()
