function bb.baseVerdict(eAd,fAd)
local gAd=(fAd.t or 0)-(eAd.t or 0)
if gAd<bb.BASE_WIN-1 then
return false
end
local hAd=((tonumber(eAd.base)or 0)-(tonumber(fAd.base)or 0))/gAd
if hAd<=0 or(tonumber(fAd.base)or 0)<=0 then
return false
end
local iAd=fAd.base/hAd
local jAd,kAd=0,0
local lAd,mAd=eAd.foes or{},fAd.foes or{}
for nAd,oAd in pairs(mAd)do
if oAd.prog>=bb.BASE_END then
jAd=jAd+oAd.hp
local pAd=lAd[nAd]
if pAd then
kAd=kAd+math.max(0,pAd.hp-oAd.hp)
end
end
end
for qAd,rAd in pairs(lAd)do
if rAd.prog>=bb.BASE_END and not mAd[qAd]then
kAd=kAd+rAd.hp
end
end
if jAd<=0 then
return false
end
local sAd=kAd/gAd
local tAd=sAd>0 and jAd/sAd or math.huge
local uAd={baseTime=iAd,loss=hAd,atEnd=jAd,rate=sAd,killTime=tAd}
return iAd<bb.BASE_SOON and tAd>iAd*bb.BASE_MARGIN,uAd
end
